select '60b3db04-aa19-533a-98de-62d652735f18', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'continuous', '{"title":"La nota definitiva","text":"En un curso, la nota definitiva se calcula así: primer corte 30 %, segundo corte 30 % y examen final 40 %. Las notas van de 0,0 a 5,0.","svg":null,"table":null}'::jsonb, 'Andrés sacó 4,0 y 2,0 en los cortes. ¿Qué plan le permite saber qué nota necesita en el final para que su definitiva sea 3,0?', '[{"label":"A","text":"Resolver 1,2 + 0,6 + 0,4x = 3,0 para x.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Lo que aportan los cortes más 0,4 por la nota final debe dar 3,0."},{"label":"B","text":"Resolver 4,0 + 2,0 + x = 3,0 para x.","is_correct":false,"distractor_type":"Suma notas sin pesos.","explanation_feedback":"Incorrecta. Las notas se multiplican por su porcentaje."},{"label":"C","text":"Promediar 4,0 y 2,0 y restar de 3,0.","is_correct":false,"distractor_type":"Ignora los porcentajes.","explanation_feedback":"Incorrecta. Cada nota pesa distinto en la definitiva."},{"label":"D","text":"Calcular 3,0 × 3 − 4,0 − 2,0.","is_correct":false,"distractor_type":"Supone que las tres notas pesan igual.","explanation_feedback":"Incorrecta. El final pesa 40 %, los cortes 30 % cada uno."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'MA.E2.1'
