select '621988d1-4406-5fe0-9277-cd2c23f0242e', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'discontinuous', '{"title":"Lectura por gusto","text":"En un colegio se preguntó a 200 estudiantes de los grados 10.° y 11.° si leen libros por gusto al menos una vez al mes.","svg":null,"table":{"caption":"Respuestas por grado","headers":["Grado","Sí lee","No lee","Total"],"rows":[["10.°",48,32,80],["11.°",63,57,120],["Total",111,89,200]]}}'::jsonb, 'Si se elige al azar un estudiante de 10.°, ¿cuál es la probabilidad de que sí lea por gusto?', '[{"label":"A","text":"0,24","is_correct":false,"distractor_type":"Divide entre el total de 200.","explanation_feedback":"Incorrecta. La condición es ser de 10.°, así que el total son 80."},{"label":"B","text":"0,6","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 48 de los 80 estudiantes de 10.° leen: 48 ÷ 80 = 0,6."},{"label":"C","text":"0,43","is_correct":false,"distractor_type":"Divide 48 entre 111.","explanation_feedback":"Incorrecta. Esa sería la proporción de lectores que son de 10.°."},{"label":"D","text":"0,48","is_correct":false,"distractor_type":"Usa 48 como porcentaje directo.","explanation_feedback":"Incorrecta. 48 es un conteo, no un porcentaje."}]'::jsonb, null, 1.1, 0, 0.25, 90, 'original_generated'
