select 'ee27ecc3-7b2c-57c9-8de1-1e86ac5208e0', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'discontinuous', '{"title":"Lectura por gusto","text":"En un colegio se preguntó a 200 estudiantes de los grados 10.° y 11.° si leen libros por gusto al menos una vez al mes.","svg":null,"table":{"caption":"Respuestas por grado","headers":["Grado","Sí lee","No lee","Total"],"rows":[["10.°",48,32,80],["11.°",63,57,120],["Total",111,89,200]]}}'::jsonb, 'Un docente concluye: «En 11.° se lee más que en 10.°, porque 63 es mayor que 48». ¿Es válida la conclusión?', '[{"label":"A","text":"Sí, porque en 11.° hay más estudiantes.","is_correct":false,"distractor_type":"Usa el tamaño del grupo como prueba.","explanation_feedback":"Incorrecta. Más estudiantes no implica que lean más en proporción."},{"label":"B","text":"No, porque en proporción leen el 52,5 % en 11.° y el 60 % en 10.°.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los grupos tienen tamaños distintos, así que hay que comparar proporciones."},{"label":"C","text":"Sí, porque 63 lectores son más que 48.","is_correct":false,"distractor_type":"Compara cantidades absolutas de grupos de distinto tamaño.","explanation_feedback":"Incorrecta. 11.° tiene 40 estudiantes más que 10.°."},{"label":"D","text":"No, porque en 10.° hay menos estudiantes que no leen.","is_correct":false,"distractor_type":"Usa un dato que no compara proporciones.","explanation_feedback":"Incorrecta. 32 contra 57 tampoco tiene en cuenta el tamaño de cada grupo."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
