select '4e6765f4-d52e-5f98-ad77-6fdd0a4550f4', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'continuous', '{"title":"Una encuesta sobre el parque","text":"La alcaldía de un municipio quiere saber si los habitantes están de acuerdo con convertir un lote en parque. Se proponen cuatro formas de hacer la encuesta.","svg":null,"table":null}'::jsonb, '¿Cuál de estas formas da resultados más representativos de todo el municipio?', '[{"label":"A","text":"Encuestar a los 30 primeros que pasen por la plaza.","is_correct":false,"distractor_type":"Usa una muestra de conveniencia.","explanation_feedback":"Incorrecta. Quienes pasan por la plaza a cierta hora no representan a todos."},{"label":"B","text":"Encuestar a personas elegidas al azar en todos los barrios.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Una muestra aleatoria y repartida reduce el sesgo."},{"label":"C","text":"Encuestar a quienes visiten la página de la alcaldía.","is_correct":false,"distractor_type":"Usa una muestra autoseleccionada.","explanation_feedback":"Incorrecta. Solo responden quienes tienen internet y les interesa el tema."},{"label":"D","text":"Encuestar solo a los vecinos del lote.","is_correct":false,"distractor_type":"Elige una muestra con un interés particular.","explanation_feedback":"Incorrecta. Los vecinos pueden pensar distinto al resto del municipio."}]'::jsonb, null, 1.1, 0, 0.25, 90, 'original_generated'
