select 'a60d11f4-472e-53ce-89e8-5df22023d73e', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'continuous', '{"title":"Una encuesta sobre el parque","text":"La alcaldía de un municipio quiere saber si los habitantes están de acuerdo con convertir un lote en parque. Se proponen cuatro formas de hacer la encuesta.","svg":null,"table":null}'::jsonb, 'En una encuesta por redes sociales, el 90 % votó a favor. Un concejal concluye que el 90 % del municipio apoya el parque. ¿Qué crítica es más adecuada?', '[{"label":"A","text":"Debió calcular la mediana y no el porcentaje.","is_correct":false,"distractor_type":"Propone una medida que no aplica.","explanation_feedback":"Incorrecta. Para respuestas sí/no se usa un porcentaje."},{"label":"B","text":"La muestra no es aleatoria: solo votó quien quiso hacerlo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los resultados de una muestra autoseleccionada no se pueden generalizar."},{"label":"C","text":"La conclusión es correcta si votaron más de 100.","is_correct":false,"distractor_type":"Cree que el tamaño corrige el sesgo.","explanation_feedback":"Incorrecta. Una muestra grande pero sesgada sigue siendo sesgada."},{"label":"D","text":"El 90 % es muy alto para ser real.","is_correct":false,"distractor_type":"Rechaza el dato sin una razón estadística.","explanation_feedback":"Incorrecta. El problema es cómo se obtuvo la muestra, no el valor."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
