abel":"B","text":"A las 16 h","is_correct":false,"distractor_type":"Lee el punto vecino.","explanation_feedback":"Incorrecta. A las 16 h había 22 °C."},{"label":"C","text":"A las 18 h","is_correct":false,"distractor_type":"Toma el último dato.","explanation_feedback":"Incorrecta. A las 18 h la temperatura ya había bajado a 18 °C."},{"label":"D","text":"A las 12 h","is_correct":false,"distractor_type":"Toma el mediodía por costumbre.","explanation_feedback":"Incorrecta. A las 12 h había 21 °C."}]'::jsonb, null, 0.9, -1.2, 0.25, 45, 'original_generated'
