select '46b6dc5d-97cd-514c-931c-5ab6009def29', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'discontinuous', '{"title":"Temperatura de un día","text":"La gráfica muestra la temperatura (°C) registrada cada dos horas en una ciudad, desde las 6 h hasta las 18 h.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 300 175\" role=\"img\" aria-label=\"Temperatura en grados Celsius según la hora\"><title>Temperatura en grados Celsius según la hora</title><line x1=\"15\" y1=\"150\" x2=\"295\" y2=\"150\" stroke=\"#333\"/><polyline points=\"30,118 70,126 110,102 150,62 190,38 230,54 270,86\" fill=\"none\" stroke=\"#d0502a\" stroke-width=\"2\"/><text x=\"30\" y=\"165\" font-size=\"10\" text-anchor=\"middle\">6h</text><text x=\"30\" y=\"110\" font-size=\"10\" text-anchor=\"middle\">14</text><text x=\"70\" y=\"165\" font-size=\"10\" text-anchor=\"middle\">8h</text><text x=\"70\" y=\"118\" font-size=\"10\" text-anchor=\"middle\">13</text><text x=\"110\" y=\"165\" font-size=\"10\" text-anchor=\"middle\">10h</text><text x=\"110\" y=\"94\" font-size=\"10\" text-anchor=\"middle\">16</text><text x=\"150\" y=\"165\" font-size=\"10\" text-anchor=\"middle\">12h</text><text x=\"150\" y=\"54\" font-size=\"10\" text-anchor=\"middle\">21</text><text x=\"190\" y=\"165\" font-size=\"10\" text-anchor=\"middle\">14h</text><text x=\"190\" y=\"30\" font-size=\"10\" text-anchor=\"middle\">24</text><text x=\"230\" y=\"165\" font-size=\"10\" text-anchor=\"middle\">16h</text><text x=\"230\" y=\"46\" font-size=\"10\" text-anchor=\"middle\">22</text><text x=\"270\" y=\"165\" font-size=\"10\" text-anchor=\"middle\">18h</text><text x=\"270\" y=\"78\" font-size=\"10\" text-anchor=\"middle\">18</text></svg>","table":null}'::jsonb, '¿Cuál fue la temperatura promedio de los siete registros, aproximada a la décima?', '[{"label":"A","text":"21,3 °C","is_correct":false,"distractor_type":"Divide entre 6 en lugar de 7.","explanation_feedback":"Incorrecta. Hay siete registros."},{"label":"B","text":"18,3 °C","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. (14 + 13 + 16 + 21 + 24 + 22 + 18) ÷ 7 = 128 ÷ 7 ≈ 18,3."},{"label":"C","text":"18,5 °C","is_correct":false,"distractor_type":"Promedia solo la máxima y la mínima.","explanation_feedback":"Incorrecta. (24 + 13) ÷ 2 = 18,5, pero el promedio usa todos los datos."},{"label":"D","text":"18,0 °C","is_correct":false,"distractor_type":"Toma la mediana.","explanation_feedback":"Incorrecta. La mediana es 18; el promedio es 128 ÷ 7."}]'::jsonb, null, 1.1, 0, 0.25, 90, 'original_generated'
