select '0f1a3296-d54f-5cdb-8564-92640076501d', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'continuous', '{"title":"Una noticia sobre precios","text":"Un periódico publicó: «El precio del kilo de tomate pasó de $2.000 en enero a $3.000 en marzo».","svg":null,"table":null}'::jsonb, '¿En qué porcentaje aumentó el precio del tomate?', '[{"label":"A","text":"150 %","is_correct":false,"distractor_type":"Da el precio final como porcentaje del inicial.","explanation_feedback":"Incorrecta. 3.000 es el 150 % de 2.000, pero el aumento es del 50 %."},{"label":"B","text":"33 %","is_correct":false,"distractor_type":"Divide el aumento entre el precio final.","explanation_feedback":"Incorrecta. El porcentaje de aumento se calcula sobre el precio inicial."},{"label":"C","text":"1.000 %","is_correct":false,"distractor_type":"Confunde el aumento en pesos con el porcentaje.","explanation_feedback":"Incorrecta. 1.000 son pesos, no un porcentaje."},{"label":"D","text":"50 %","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El aumento es 1.000 y 1.000 ÷ 2.000 = 0,5."}]'::jsonb, null, 0.9, -1.2, 0.25, 60, 'original_generated'
