select 'fb001684-0690-5eff-8dc5-648d555411b7', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'continuous', '{"title":"Una noticia sobre precios","text":"Un periódico publicó: «El precio del kilo de tomate pasó de $2.000 en enero a $3.000 en marzo».","svg":null,"table":null}'::jsonb, 'En abril el precio volvió a bajar un 50 %. Un lector dice que regresó a $2.000. ¿Tiene razón?', '[{"label":"A","text":"Sí, porque subir 50 % y bajar 50 % se anulan.","is_correct":false,"distractor_type":"Cree que los porcentajes opuestos se cancelan.","explanation_feedback":"Incorrecta. Las bases de los porcentajes son distintas."},{"label":"B","text":"No, bajó a $1.000, porque se restan 2.000.","is_correct":false,"distractor_type":"Resta un valor que no es el 50 %.","explanation_feedback":"Incorrecta. El 50 % de 3.000 es 1.500."},{"label":"C","text":"Sí, porque en abril bajó $1.000.","is_correct":false,"distractor_type":"Calcula mal la rebaja.","explanation_feedback":"Incorrecta. Una rebaja del 50 % de 3.000 son 1.500, no 1.000."},{"label":"D","text":"No, bajó a $1.500: el 50 % es sobre $3.000.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 3.000 × 0,5 = 1.500."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
