select '2dc0df04-26c5-5861-a5ed-ec0277f0ac38', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.EST'), 'qa_passed', 'discontinuous', '{"title":"Tiempos de una carrera","text":"Dos grupos de atletas corrieron 400 m. Se resumen sus tiempos (en segundos).","svg":null,"table":{"caption":"Resumen de los tiempos (s)","headers":["Grupo","Mínimo","Cuartil 1","Mediana","Cuartil 3","Máximo"],"rows":[["A",58,62,65,70,81],["B",60,63,64,66,69]]}}'::jsonb, 'Un entrenador dice: «Los tiempos del grupo B son más parejos». ¿Qué dato respalda mejor su afirmación?', '[{"label":"A","text":"El mínimo de A es menor que el de B.","is_correct":false,"distractor_type":"Usa un dato extremo aislado.","explanation_feedback":"Incorrecta. Un mínimo solo no mide la dispersión."},{"label":"B","text":"La mediana de B es menor que la de A.","is_correct":false,"distractor_type":"Usa una medida de posición, no de dispersión.","explanation_feedback":"Incorrecta. La mediana no dice qué tan parejos son los datos."},{"label":"C","text":"El rango intercuartílico de B es 3 s y el de A es 8 s.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La mitad central de B está mucho más concentrada."},{"label":"D","text":"El máximo de B es 69 s.","is_correct":false,"distractor_type":"Da un dato sin comparar dispersión.","explanation_feedback":"Incorrecta. Hay que comparar rangos o cuartiles."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
